#!/usr/bin/env python3
"""Non-destructive Ventoy probe with generated bytes only, no real artifact copy."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import secrets
import shutil
import subprocess
import tarfile
import tempfile
import time
import uuid
from ueba_research_artifacts import private_directory,commit

p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);p.add_argument('--usb',type=Path,required=True);a=p.parse_args()
root=private_directory(a.output.resolve());usb=a.usb.resolve()
mount=json.loads(subprocess.check_output(['findmnt','--json','--target',str(usb),'-o','TARGET,SOURCE,FSTYPE'],text=True))['filesystems'][0]
if Path(mount['target'])!=usb or mount['fstype']!='exfat':raise ValueError('exact inspected exFAT mount required; no device formatting')
if shutil.disk_usage(usb).free<5_000_000_000+32*1024**2:raise ValueError('USB reserve insufficient')
identity=usb.stat().st_dev;folder=usb/('.flare-preparation-probe-'+uuid.uuid4().hex)
folder.mkdir(mode=0o700);encrypted=folder/'generated-fixture.tar.gpg'
try:
    with tempfile.TemporaryDirectory(prefix='usb-probe-',dir=root) as tmp:
        work=Path(tmp);source=work/'source';restore=work/'restore';home=work/'gnupg'
        for d in (source,restore,home):d.mkdir(mode=0o700)
        original=source/'original.bin';original.write_bytes(secrets.token_bytes(8*1024**2));original.chmod(0o600)
        os.link(original,source/'alias.bin');expected=hashlib.sha256(original.read_bytes()).hexdigest()
        archive=work/'generated.tar'
        with tarfile.open(archive,'w',dereference=False) as t:
            t.add(original,arcname='original.bin');t.add(source/'alias.bin',arcname='alias.bin')
        key=secrets.token_hex(32).encode()+b'\n'
        base=['gpg','--homedir',str(home),'--batch','--yes','--no-symkey-cache','--pinentry-mode','loopback','--passphrase-fd','0']
        start=time.monotonic()
        subprocess.run(base+['--symmetric','--cipher-algo','AES256','--output',str(encrypted),str(archive)],input=key,check=True,capture_output=True,timeout=90)
        with encrypted.open('rb') as f:os.fsync(f.fileno())
        write_seconds=time.monotonic()-start;size=encrypted.stat().st_size
        assert usb.stat().st_dev==identity
        restored=work/'readback.tar';start=time.monotonic()
        subprocess.run(base+['--decrypt','--output',str(restored),str(encrypted)],input=key,check=True,capture_output=True,timeout=90)
        read_seconds=time.monotonic()-start
        with tarfile.open(restored,'r:') as t:
            members=t.getmembers();assert [m.name for m in members]==['original.bin','alias.bin']
            assert members[0].isreg() and members[1].islnk() and members[1].linkname=='original.bin'
            t.extractall(restore,filter='data')
        assert hashlib.sha256((restore/'original.bin').read_bytes()).hexdigest()==expected
        assert (restore/'original.bin').stat().st_ino==(restore/'alias.bin').stat().st_ino
        subprocess.run(['gpgconf','--homedir',str(home),'--kill','gpg-agent'],capture_output=True,timeout=10)
        report={'status':'USB_GENERATED_FIXTURE_ENCRYPTED_READBACK_RESTORE_PASS','mount':str(usb),'device':mount['source'],'filesystem':mount['fstype'],
            'capacity_bytes':shutil.disk_usage(usb).total,'free_bytes_before_cleanup':shutil.disk_usage(usb).free,
            'generated_bytes':8*1024**2,'encrypted_bytes':size,'encrypted_write_and_sync_seconds':write_seconds,'decrypt_readback_seconds':read_seconds,
            'fixture_sha256':expected,'hardlink_group_restored_on_ssd':True,'encryption':'AES256_GPG_GENERATED_EPHEMERAL_TEST_KEY',
            'real_artifacts_copied':0,'existing_usb_files_modified':False,'formatted':False,
            'not_full_campaign_capacity_or_powerloss_proof':True,'new_fits':0}
finally:
    if encrypted.exists():encrypted.unlink()
    folder.rmdir()
report['probe_files_removed']=True;report['usb_free_bytes']=shutil.disk_usage(usb).free
commit(root,report,phase='usb-probe-v1');print(json.dumps({k:report[k] for k in ('status','usb_free_bytes','encrypted_write_and_sync_seconds','decrypt_readback_seconds','real_artifacts_copied','probe_files_removed')}))
